-- ============================================================
-- Projeto: Banco de Dados da Rafimex Comercial Importação e Exportação Ltda
--          (Rafimex Mesa Posta e Decorações)
-- Entrega 2 - Modelo Lógico e Implementação SQL
-- Grupo: Anderson Rafael da Silva, Leticia Souza Santos,
--        Maria Eduarda Sobrinho dos Santos, Nathan Vieira De Lara,
--        Ketlyn Nayara da Silva Cezar
-- SGBD: MySQL 8.0 (InnoDB, utf8mb4) - testado no MySQL 8.0.40
--
--
-- Todos os dados são fictícios (nomes, CNPJs, CPFs e valores
-- inventados). CNPJ, CPF e chave de acesso da NF-e têm dígitos
-- verificadores válidos, mas não pertencem a ninguém.
--
-- Problemas da Rafimex que o banco resolve (citados nas consultas):
--   P1 - Cadastro de cliente desatualizado sem nenhum aviso prévio
--        (a empresa só descobre depois do prejuízo).
--   P2 - Boleto não recebido por contato financeiro errado, virando
--        inadimplência.
--   P3 - Devolução e taxa de reentrega por endereço desatualizado.
--
-- Indicadores (KPIs) calculados nas consultas gerenciais:
--   K1 - Faturamento mensal e ticket médio ............... G01
--   K2 - % da carteira com cadastro vencido (> 90 dias) .. G03
--   K3 - Taxa de inadimplência dos boletos ............... G04
--   K4 - Taxa de devolução e custo de reentrega .......... G05
--   K5 - Comissão liberada x retida por colaborador ...... G06
--   K6 - Taxa de cancelamento de pedidos ................. G09
-- ============================================================


-- ============================================================
-- 1. CREATE DATABASE
-- ============================================================
DROP DATABASE IF EXISTS db_rafimex;
CREATE DATABASE db_rafimex
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;
USE db_rafimex;


-- ============================================================
-- 2 e 3. CREATE TABLE + CONSTRAINTS (PK, FK, NOT NULL, UNIQUE, CHECK)
-- Ordem: primeiro as tabelas sem FK, depois as que dependem delas.
-- ============================================================

-- ---------- Tabelas de domínio (criadas na 3FN) ----------
-- Na Entrega 1, frete, forma de pagamento e status eram texto livre
-- dentro de PEDIDO. Viraram tabelas para não repetir o texto em cada
-- pedido e para impedir valores digitados errado ("boleto", "Boleto ").

CREATE TABLE TIPO_FRETE (
    ID_TIPO_FRETE  INT AUTO_INCREMENT PRIMARY KEY,
    DS_TIPO_FRETE  VARCHAR(30) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE FORMA_PAGAMENTO (
    ID_FORMA_PAGAMENTO  INT AUTO_INCREMENT PRIMARY KEY,
    DS_FORMA_PAGAMENTO  VARCHAR(30) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE STATUS_PEDIDO (
    ID_STATUS_PEDIDO  INT AUTO_INCREMENT PRIMARY KEY,
    DS_STATUS_PEDIDO  VARCHAR(30) NOT NULL UNIQUE
) ENGINE=InnoDB;

-- RN12: o percentual de comissão depende só do tipo de vínculo (8% externo,
-- 3% interno). Guardar o percentual em cada colaborador seria uma dependência
-- transitiva (ID_COLABORADOR -> tipo -> percentual), por isso fica aqui (3FN).
CREATE TABLE TIPO_COLABORADOR (
    ID_TIPO_COLABORADOR  INT AUTO_INCREMENT PRIMARY KEY,
    DS_TIPO_COLABORADOR  VARCHAR(10)  NOT NULL UNIQUE,
    VL_PERC_COMISSAO     DECIMAL(5,2) NOT NULL,
    CONSTRAINT CK_TIPOCOLAB_COMISSAO CHECK (VL_PERC_COMISSAO BETWEEN 0 AND 20)
) ENGINE=InnoDB;

-- ---------- Cadastros ----------

CREATE TABLE COLABORADOR (
    ID_COLABORADOR         INT AUTO_INCREMENT PRIMARY KEY,
    ID_TIPO_COLABORADOR    INT          NOT NULL,
    NM_COLABORADOR         VARCHAR(120) NOT NULL,
    NR_CPF                 VARCHAR(14)  NOT NULL UNIQUE,
    DT_DATA_DE_NASCIMENTO  DATE         NOT NULL,
    CD_CEP                 VARCHAR(9)   NOT NULL,
    CD_UF                  CHAR(2)      NOT NULL,
    DS_CIDADE              VARCHAR(100) NOT NULL,
    DS_BAIRRO              VARCHAR(100) NOT NULL,
    DS_RUA                 VARCHAR(150) NOT NULL,
    NR_NUMERO              VARCHAR(10)  NOT NULL,
    DS_COMPLEMENTO         VARCHAR(100),
    DS_EMAIL               VARCHAR(100) NOT NULL,
    CD_DDD                 CHAR(2)      NOT NULL,
    NR_NUMERO_TEL          VARCHAR(14)  NOT NULL,
    CONSTRAINT CK_COLAB_CPF   CHECK (NR_CPF REGEXP '^[0-9]{3}[.][0-9]{3}[.][0-9]{3}-[0-9]{2}$'),
    CONSTRAINT CK_COLAB_CEP   CHECK (CD_CEP REGEXP '^[0-9]{5}-[0-9]{3}$'),
    CONSTRAINT CK_COLAB_EMAIL CHECK (DS_EMAIL LIKE '%_@_%._%'),
    CONSTRAINT FK_COLAB_TIPO  FOREIGN KEY (ID_TIPO_COLABORADOR) REFERENCES TIPO_COLABORADOR(ID_TIPO_COLABORADOR)
) ENGINE=InnoDB;

CREATE INDEX IX_COLABORADOR_NOME ON COLABORADOR (NM_COLABORADOR);

CREATE TABLE CLIENTE (
    ID_CLIENTE              INT AUTO_INCREMENT PRIMARY KEY,
    ID_COLABORADOR          INT          NOT NULL,   -- representante que atende o cliente (COLABORADOR 1:N CLIENTE)
    NM_RAZAO_SOCIAL         VARCHAR(100) NOT NULL,
    NR_CNPJ                 VARCHAR(18)  NOT NULL UNIQUE,
    NR_INSCRIC_ESTADUAL     VARCHAR(20),
    CD_CEP                  VARCHAR(9)   NOT NULL,
    CD_UF                   CHAR(2)      NOT NULL,
    DS_CIDADE               VARCHAR(100) NOT NULL,
    DS_BAIRRO               VARCHAR(100) NOT NULL,
    DS_RUA                  VARCHAR(150) NOT NULL,
    NR_NUMERO               VARCHAR(10)  NOT NULL,
    DS_COMPLEMENTO          VARCHAR(100),
    DS_EMAIL                VARCHAR(100) NOT NULL,
    CD_DDD                  CHAR(2)      NOT NULL,
    NR_NUMERO_TEL           VARCHAR(10)  NOT NULL,
    VL_LIMITE_CREDITO       DECIMAL(15,2) NOT NULL DEFAULT 0,
    IN_ATIVO                BOOLEAN      NOT NULL DEFAULT TRUE,
    ID_SERASA               VARCHAR(50)  NOT NULL,
    ST_SITUACAO_CREDITO     VARCHAR(20)  NOT NULL DEFAULT 'Ativo',
    DT_DATA_DE_ATUALIZACAO  DATE         NOT NULL,   -- RN09 / RF09: base da trava de 90 dias
    CONSTRAINT CK_CLIENTE_CNPJ     CHECK (NR_CNPJ REGEXP '^[0-9]{2}[.][0-9]{3}[.][0-9]{3}/[0-9]{4}-[0-9]{2}$'),  -- RF01 / RN01
    CONSTRAINT CK_CLIENTE_CEP      CHECK (CD_CEP REGEXP '^[0-9]{5}-[0-9]{3}$'),
    CONSTRAINT CK_CLIENTE_EMAIL    CHECK (DS_EMAIL LIKE '%_@_%._%'),
    CONSTRAINT CK_CLIENTE_LIMITE   CHECK (VL_LIMITE_CREDITO >= 0),
    CONSTRAINT CK_CLIENTE_SITUACAO CHECK (ST_SITUACAO_CREDITO IN ('Ativo','Bloqueado Serasa','Inadimplente')),
    CONSTRAINT FK_CLIENTE_COLABORADOR FOREIGN KEY (ID_COLABORADOR) REFERENCES COLABORADOR(ID_COLABORADOR)
) ENGINE=InnoDB;

CREATE INDEX IX_CLIENTE_RAZAO_SOCIAL   ON CLIENTE (NM_RAZAO_SOCIAL);
CREATE INDEX IX_CLIENTE_DT_ATUALIZACAO ON CLIENTE (DT_DATA_DE_ATUALIZACAO);

CREATE TABLE PRODUTO (
    ID_PRODUTO         INT AUTO_INCREMENT PRIMARY KEY,
    CD_SKU             VARCHAR(30)   NOT NULL UNIQUE,
    CD_NCM             VARCHAR(10)   NOT NULL,
    DS_DESCRICAO       VARCHAR(150)  NOT NULL,
    VL_PRECO_CUSTO     NUMERIC(10,2) NOT NULL,
    VL_PRECO_UNITARIO  NUMERIC(10,2) NOT NULL,
    QT_ESTOQUE         INT NOT NULL DEFAULT 0,
    QT_PONTO_PEDIDO    INT NOT NULL DEFAULT 0,   -- RF08: abaixo disso, alerta de reposição
    CONSTRAINT CK_PRODUTO_CUSTO   CHECK (VL_PRECO_CUSTO > 0),
    CONSTRAINT CK_PRODUTO_PRECO   CHECK (VL_PRECO_UNITARIO > 0),
    CONSTRAINT CK_PRODUTO_ESTOQUE CHECK (QT_ESTOQUE >= 0),
    CONSTRAINT CK_PRODUTO_PONTO   CHECK (QT_PONTO_PEDIDO >= 0)
) ENGINE=InnoDB;

CREATE INDEX IX_PRODUTO_NCM ON PRODUTO (CD_NCM);

-- RN10: compra e importação só com fornecedor cadastrado com CNPJ válido.
CREATE TABLE FORNECEDOR (
    ID_FORNECEDOR        INT AUTO_INCREMENT PRIMARY KEY,
    NR_CNPJ              VARCHAR(18)  NOT NULL UNIQUE,
    NM_RAZAO_SOCIAL      VARCHAR(100) NOT NULL,
    NR_INSCRIC_ESTADUAL  VARCHAR(20),
    DS_EMAIL             VARCHAR(100) NOT NULL,
    CD_DDD               CHAR(2)      NOT NULL,
    NR_NUMERO_TEL        VARCHAR(10)  NOT NULL,
    CD_CEP               VARCHAR(9)   NOT NULL,
    CD_UF                CHAR(2)      NOT NULL,
    DS_CIDADE            VARCHAR(100) NOT NULL,
    DS_BAIRRO            VARCHAR(100) NOT NULL,
    DS_RUA               VARCHAR(150) NOT NULL,
    NR_NUMERO_ENDERECO   VARCHAR(10)  NOT NULL,
    DS_COMPLEMENTO       VARCHAR(100),
    CONSTRAINT CK_FORNECEDOR_CNPJ  CHECK (NR_CNPJ REGEXP '^[0-9]{2}[.][0-9]{3}[.][0-9]{3}/[0-9]{4}-[0-9]{2}$'),
    CONSTRAINT CK_FORNECEDOR_CEP   CHECK (CD_CEP REGEXP '^[0-9]{5}-[0-9]{3}$'),
    CONSTRAINT CK_FORNECEDOR_EMAIL CHECK (DS_EMAIL LIKE '%_@_%._%')
) ENGINE=InnoDB;

CREATE INDEX IX_FORNECEDOR_RAZAO_SOCIAL ON FORNECEDOR (NM_RAZAO_SOCIAL);

-- FORNECEDOR (1,n) fornece (1,n) PRODUTO: o N:N vira tabela associativa.
CREATE TABLE FORNECEDOR_PRODUTO (
    ID_FORNECEDOR  INT NOT NULL,
    ID_PRODUTO     INT NOT NULL,
    PRIMARY KEY (ID_FORNECEDOR, ID_PRODUTO),
    CONSTRAINT FK_FORNPROD_FORNECEDOR FOREIGN KEY (ID_FORNECEDOR) REFERENCES FORNECEDOR(ID_FORNECEDOR),
    CONSTRAINT FK_FORNPROD_PRODUTO    FOREIGN KEY (ID_PRODUTO)    REFERENCES PRODUTO(ID_PRODUTO)
) ENGINE=InnoDB;

-- ---------- Ciclo de vendas ----------

CREATE TABLE PEDIDO (
    ID_PEDIDO               INT AUTO_INCREMENT PRIMARY KEY,
    ID_CLIENTE              INT NOT NULL,             -- RF03 / RN05
    ID_COLABORADOR          INT NOT NULL,             -- RF03 / RN05: quem emitiu o pedido
    DT_DATA_DO_PEDIDO       DATE NOT NULL,
    VL_VALOR_VENDA          DECIMAL(18,2) NOT NULL,   -- total já com o desconto aplicado
    ID_TIPO_FRETE           INT NOT NULL,             -- RF06
    ID_FORMA_PAGAMENTO      INT NOT NULL,
    VL_DESCONTO_APLICADO    DECIMAL(8,2) NOT NULL DEFAULT 0,   -- em %
    IN_APROVACAO_DIRETORIA  BOOLEAN NOT NULL DEFAULT FALSE,    -- RF04
    ID_STATUS_PEDIDO        INT NOT NULL,
    CONSTRAINT CK_PEDIDO_VALOR    CHECK (VL_VALOR_VENDA > 0),
    CONSTRAINT CK_PEDIDO_DESCONTO CHECK (VL_DESCONTO_APLICADO BETWEEN 0 AND 100),
    -- RN06 / RF04: desconto acima de 4% só com aprovação da diretoria registrada
    CONSTRAINT CK_PEDIDO_APROVACAO CHECK (VL_DESCONTO_APLICADO <= 4 OR IN_APROVACAO_DIRETORIA = TRUE),
    CONSTRAINT FK_PEDIDO_CLIENTE     FOREIGN KEY (ID_CLIENTE)         REFERENCES CLIENTE(ID_CLIENTE),
    CONSTRAINT FK_PEDIDO_COLABORADOR FOREIGN KEY (ID_COLABORADOR)     REFERENCES COLABORADOR(ID_COLABORADOR),
    CONSTRAINT FK_PEDIDO_TIPO_FRETE  FOREIGN KEY (ID_TIPO_FRETE)      REFERENCES TIPO_FRETE(ID_TIPO_FRETE),
    CONSTRAINT FK_PEDIDO_FORMA_PGTO  FOREIGN KEY (ID_FORMA_PAGAMENTO) REFERENCES FORMA_PAGAMENTO(ID_FORMA_PAGAMENTO),
    CONSTRAINT FK_PEDIDO_STATUS      FOREIGN KEY (ID_STATUS_PEDIDO)   REFERENCES STATUS_PEDIDO(ID_STATUS_PEDIDO)
) ENGINE=InnoDB;

CREATE INDEX IX_PEDIDO_DATA ON PEDIDO (DT_DATA_DO_PEDIDO);

-- PEDIDO (0,n) contém (1,n) PRODUTO: o N:N vira ITEM_PEDIDO, com PK composta
-- e os atributos do relacionamento (qtd_item, vlr_preco_praticado, data_prev_chegada).
CREATE TABLE ITEM_PEDIDO (
    ID_PEDIDO            INT NOT NULL,
    ID_PRODUTO           INT NOT NULL,
    QT_VENDIDA           INT NOT NULL,
    VL_UNITARIO_VENDIDO  DECIMAL(10,2) NOT NULL,   -- RF05 / RN07: preço do dia da venda
    DT_PREVISAO_CHEGADA  DATE,                     -- RF07 / RN08: vazio = sai do estoque; preenchido = entrega programada
    PRIMARY KEY (ID_PEDIDO, ID_PRODUTO),
    CONSTRAINT CK_ITEM_PEDIDO_QTD   CHECK (QT_VENDIDA > 0),
    CONSTRAINT CK_ITEM_PEDIDO_VALOR CHECK (VL_UNITARIO_VENDIDO > 0),
    CONSTRAINT FK_ITEMPED_PEDIDO  FOREIGN KEY (ID_PEDIDO)  REFERENCES PEDIDO(ID_PEDIDO) ON DELETE CASCADE,
    CONSTRAINT FK_ITEMPED_PRODUTO FOREIGN KEY (ID_PRODUTO) REFERENCES PRODUTO(ID_PRODUTO)
) ENGINE=InnoDB;

-- PEDIDO (1,1) emite (0,1) NOTA_FISCAL: 1:1 vira FK com UNIQUE.
-- Devolução / reentrega (P3 e RN13): cada nota volta no máximo uma vez,
-- por isso os dados da devolução são atributos da nota (vazios quando a
-- entrega deu certo).
CREATE TABLE NOTA_FISCAL (
    ID_NF                  INT AUTO_INCREMENT PRIMARY KEY,
    ID_PEDIDO              INT NOT NULL UNIQUE,
    NR_NF                  INT NOT NULL UNIQUE,
    NR_CHAVE_ACESSO        VARCHAR(44) NOT NULL UNIQUE,
    DT_DATA_EMISSAO        DATE NOT NULL,
    VL_IMPOSTO_IMPORTACAO  DECIMAL(18,2),            -- só quando a nota tem produto importado
    VL_TOTAL_IMPOSTOS      DECIMAL(18,2) NOT NULL,
    VL_TOTAL_NF            DECIMAL(18,2) NOT NULL,
    DS_STATUS_NF           VARCHAR(20) NOT NULL DEFAULT 'Emitida',
    DT_DEVOLUCAO           DATE,                     -- P3: data em que a mercadoria voltou
    DS_MOTIVO_DEVOLUCAO    VARCHAR(30),
    VL_TAXA_REENTREGA      DECIMAL(10,2),
    CONSTRAINT CK_NF_CHAVE   CHECK (NR_CHAVE_ACESSO REGEXP '^[0-9]{44}$'),
    CONSTRAINT CK_NF_VALORES CHECK (VL_TOTAL_NF > 0 AND VL_TOTAL_IMPOSTOS >= 0 AND VL_TOTAL_IMPOSTOS < VL_TOTAL_NF),
    CONSTRAINT CK_NF_STATUS  CHECK (DS_STATUS_NF IN ('Emitida','Cancelada')),
    CONSTRAINT CK_NF_DEVOLUCAO CHECK (
        (DT_DEVOLUCAO IS NULL AND DS_MOTIVO_DEVOLUCAO IS NULL AND VL_TAXA_REENTREGA IS NULL) OR
        (DT_DEVOLUCAO IS NOT NULL AND DS_MOTIVO_DEVOLUCAO IS NOT NULL AND VL_TAXA_REENTREGA >= 0)),
    CONSTRAINT CK_NF_DEV_MOTIVO CHECK (DS_MOTIVO_DEVOLUCAO IN ('Endereço desatualizado','Avaria no transporte','Recusa do cliente')),
    CONSTRAINT CK_NF_DEV_DATA   CHECK (DT_DEVOLUCAO IS NULL OR DT_DEVOLUCAO >= DT_DATA_EMISSAO),
    CONSTRAINT FK_NF_PEDIDO  FOREIGN KEY (ID_PEDIDO) REFERENCES PEDIDO(ID_PEDIDO)
) ENGINE=InnoDB;

CREATE INDEX IX_NF_DT_EMISSAO ON NOTA_FISCAL (DT_DATA_EMISSAO);

-- Cobrança (P2 e RN12): NOTA_FISCAL (1,1) gera (1,n) TITULO_RECEBER.
-- O boleto pode ser parcelado (30/60/90 dias): uma parcela por título.
-- PIX e cartão geram um único título, já pago na emissão.
-- "Vencido" não é guardado: é calculado (em aberto e com vencimento antes
-- de hoje), para nunca ficar desatualizado. A pendência interna do cliente
-- (RN04) é derivada daqui: título vencido e não pago.
CREATE TABLE TITULO_RECEBER (
    ID_TITULO         INT AUTO_INCREMENT PRIMARY KEY,
    ID_NF             INT NOT NULL,
    NR_PARCELA        INT NOT NULL DEFAULT 1,
    DT_VENCIMENTO     DATE NOT NULL,
    VL_PARCELA        DECIMAL(18,2) NOT NULL,
    DT_PAGAMENTO      DATE,
    ST_STATUS_TITULO  VARCHAR(20) NOT NULL DEFAULT 'Aberto',
    CONSTRAINT UQ_TITULO_NF_PARCELA UNIQUE (ID_NF, NR_PARCELA),
    CONSTRAINT CK_TITULO_PARCELA    CHECK (NR_PARCELA BETWEEN 1 AND 12),
    CONSTRAINT CK_TITULO_VALOR      CHECK (VL_PARCELA > 0),
    CONSTRAINT CK_TITULO_STATUS     CHECK (ST_STATUS_TITULO IN ('Aberto','Pago','Cancelado')),
    CONSTRAINT CK_TITULO_PAGO       CHECK ((ST_STATUS_TITULO = 'Pago') = (DT_PAGAMENTO IS NOT NULL)),
    CONSTRAINT FK_TITULO_NF         FOREIGN KEY (ID_NF) REFERENCES NOTA_FISCAL(ID_NF)
) ENGINE=InnoDB;

CREATE INDEX IX_TITULO_VENCIMENTO ON TITULO_RECEBER (DT_VENCIMENTO);

-- ---------- Ciclo de compras (reposição e importações) ----------

-- FORNECEDOR (1,1) pertence (0,n) COMPRA / IMPORTAÇÃO: FK no lado N.
-- Contas a pagar (RN11): cada compra gera exatamente uma conta, por isso o
-- vencimento, o pagamento e a situação são atributos da própria compra.
-- A compra cancelada não gera conta (campos vazios).
CREATE TABLE COMPRA_IMPORTACAO (
    ID_COMPRA            INT AUTO_INCREMENT PRIMARY KEY,
    ID_FORNECEDOR        INT NOT NULL,                -- RN10
    NR_NUMERO_COMPRA     VARCHAR(20) NOT NULL UNIQUE,
    TP_TIPO_OPERACAO     VARCHAR(20) NOT NULL,        -- compra nacional ou importação
    DT_DATA_COMPRA       DATE NOT NULL,
    DT_PREVISAO_CHEGADA  DATE,                        -- RN08 / RN11: permite vender estoque futuro
    DT_DATA_RECEBIMENTO  DATE,                        -- preenchida quando a mercadoria chega
    VL_VALOR_TOTAL       DECIMAL(18,2) NOT NULL,      -- em reais (convertido na data da compra)
    CD_MOEDA             CHAR(3) NOT NULL DEFAULT 'BRL',   -- moeda da negociação (ISO 4217)
    DS_INCOTERM          VARCHAR(3),                  -- só na importação (FOB, CIF...)
    ST_STATUS_COMPRA     VARCHAR(20) NOT NULL DEFAULT 'Pendente',
    DT_VENCIMENTO_PAGAMENTO  DATE,                    -- RN11: conta a pagar ao fornecedor
    DT_PAGAMENTO             DATE,
    ST_STATUS_PAGAMENTO      VARCHAR(20),
    CONSTRAINT CK_COMPRA_PGTO_STATUS CHECK (ST_STATUS_PAGAMENTO IN ('Pendente','Pago')),
    CONSTRAINT CK_COMPRA_CONTA CHECK (
        (ST_STATUS_COMPRA = 'Cancelado' AND DT_VENCIMENTO_PAGAMENTO IS NULL AND ST_STATUS_PAGAMENTO IS NULL AND DT_PAGAMENTO IS NULL) OR
        (ST_STATUS_COMPRA <> 'Cancelado' AND DT_VENCIMENTO_PAGAMENTO IS NOT NULL AND ST_STATUS_PAGAMENTO IS NOT NULL
         AND (ST_STATUS_PAGAMENTO = 'Pago') = (DT_PAGAMENTO IS NOT NULL))),
    CONSTRAINT CK_COMPRA_TIPO      CHECK (TP_TIPO_OPERACAO IN ('Compra nacional','Importação')),
    CONSTRAINT CK_COMPRA_MOEDA      CHECK (CD_MOEDA IN ('BRL','USD','EUR','CNY')),
    CONSTRAINT CK_COMPRA_INCOTERM   CHECK (DS_INCOTERM IN ('EXW','FOB','CFR','CIF','DAP','DDP')),
    CONSTRAINT CK_COMPRA_IMPORTACAO CHECK ((TP_TIPO_OPERACAO = 'Importação') = (DS_INCOTERM IS NOT NULL)),
    CONSTRAINT CK_COMPRA_DATAS      CHECK (DT_PREVISAO_CHEGADA IS NULL OR DT_PREVISAO_CHEGADA >= DT_DATA_COMPRA),
    CONSTRAINT CK_COMPRA_RECEBIDA   CHECK ((ST_STATUS_COMPRA = 'Recebido') = (DT_DATA_RECEBIMENTO IS NOT NULL)),
    CONSTRAINT CK_COMPRA_RECEB_DATA CHECK (DT_DATA_RECEBIMENTO IS NULL OR DT_DATA_RECEBIMENTO >= DT_DATA_COMPRA),
    CONSTRAINT CK_COMPRA_VALOR      CHECK (VL_VALOR_TOTAL > 0),
    CONSTRAINT CK_COMPRA_STATUS     CHECK (ST_STATUS_COMPRA IN ('Pendente','Recebido','Cancelado')),
    CONSTRAINT FK_COMPRA_FORNECEDOR FOREIGN KEY (ID_FORNECEDOR) REFERENCES FORNECEDOR(ID_FORNECEDOR)
) ENGINE=InnoDB;

CREATE INDEX IX_COMPRA_STATUS ON COMPRA_IMPORTACAO (ST_STATUS_COMPRA);
CREATE INDEX IX_COMPRA_DATA   ON COMPRA_IMPORTACAO (DT_DATA_COMPRA);

-- PRODUTO (1,n) inclui (0,n) COMPRA / IMPORTAÇÃO: o N:N vira ITEM_COMPRA (atributo qnt_comprada).
CREATE TABLE ITEM_COMPRA (
    ID_COMPRA                 INT NOT NULL,
    ID_PRODUTO                INT NOT NULL,
    QT_COMPRADA               INT NOT NULL,
    VL_CUSTO_UNITARIO_COMPRA  DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (ID_COMPRA, ID_PRODUTO),
    CONSTRAINT CK_ITEMCOMPRA_QTD   CHECK (QT_COMPRADA > 0),
    CONSTRAINT CK_ITEMCOMPRA_CUSTO CHECK (VL_CUSTO_UNITARIO_COMPRA > 0),
    CONSTRAINT FK_ITEMCOMPRA_COMPRA  FOREIGN KEY (ID_COMPRA)  REFERENCES COMPRA_IMPORTACAO(ID_COMPRA) ON DELETE CASCADE,
    CONSTRAINT FK_ITEMCOMPRA_PRODUTO FOREIGN KEY (ID_PRODUTO) REFERENCES PRODUTO(ID_PRODUTO)
) ENGINE=InnoDB;

-- ---------- Auditoria de acesso (RNF04 e LGPD) ----------
-- Tabela técnica: registra quem leu ou alterou dados cadastrais e
-- financeiros. Não é um dado do negócio, por isso não aparece no DER.
-- O usuário é guardado por login e perfil (e não por FK), porque quem
-- acessa também pode ser do financeiro, do RH ou do faturamento, que não
-- estão na tabela COLABORADOR (equipe comercial).
CREATE TABLE LOG_ACESSO (
    ID_LOG             INT AUTO_INCREMENT PRIMARY KEY,
    NM_USUARIO         VARCHAR(60) NOT NULL,
    DS_PERFIL          VARCHAR(20) NOT NULL,
    DT_ACESSO          DATETIME    NOT NULL,
    DS_OPERACAO        VARCHAR(10) NOT NULL,
    DS_TABELA_AFETADA  VARCHAR(30) NOT NULL,
    NR_ID_REGISTRO     INT,                        -- chave do registro acessado, quando houver
    CONSTRAINT CK_LOG_PERFIL   CHECK (DS_PERFIL IN ('Vendedor','Financeiro','Faturamento','Compras','RH','Administrador')),
    CONSTRAINT CK_LOG_OPERACAO CHECK (DS_OPERACAO IN ('Ler','Inserir','Atualizar','Apagar'))
) ENGINE=InnoDB;

CREATE INDEX IX_LOG_DATA   ON LOG_ACESSO (DT_ACESSO);
CREATE INDEX IX_LOG_TABELA ON LOG_ACESSO (DS_TABELA_AFETADA);

-- ---------- Regras de negócio que um CHECK não consegue garantir ----------
-- CHECK só enxerga a própria linha. As regras abaixo precisam olhar o
-- cadastro do cliente e as devoluções, então ficam em triggers.
--
-- A validação vale para pedidos com data de hoje em diante. Os pedidos
-- antigos da carga histórica (bloco 4) já foram aprovados na época em
-- que foram feitos; por isso não passam pela trava de novo.

DELIMITER $$

CREATE TRIGGER TRG_PEDIDO_VALIDA_CLIENTE
BEFORE INSERT ON PEDIDO
FOR EACH ROW
BEGIN
    DECLARE v_ativo          BOOLEAN;
    DECLARE v_situacao       VARCHAR(20);
    DECLARE v_dt_atualizacao DATE;
    DECLARE v_limite         DECIMAL(15,2);
    DECLARE v_forma          VARCHAR(30);

    IF NEW.DT_DATA_DO_PEDIDO >= CURDATE() THEN
        SELECT IN_ATIVO, ST_SITUACAO_CREDITO, DT_DATA_DE_ATUALIZACAO, VL_LIMITE_CREDITO
          INTO v_ativo, v_situacao, v_dt_atualizacao, v_limite
          FROM CLIENTE
         WHERE ID_CLIENTE = NEW.ID_CLIENTE;

        SELECT DS_FORMA_PAGAMENTO INTO v_forma
          FROM FORMA_PAGAMENTO
         WHERE ID_FORMA_PAGAMENTO = NEW.ID_FORMA_PAGAMENTO;

        IF v_ativo = FALSE THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cliente inativo: pedido bloqueado.';
        END IF;

        IF v_situacao = 'Inadimplente' THEN                               -- RN04 / RF02
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: cliente inadimplente com a Rafimex. Pedido bloqueado.';
        END IF;

        IF EXISTS (SELECT 1                                               -- RN13
                     FROM NOTA_FISCAL nf
                     JOIN PEDIDO p ON p.ID_PEDIDO = nf.ID_PEDIDO
                    WHERE p.ID_CLIENTE = NEW.ID_CLIENTE
                      AND nf.DS_MOTIVO_DEVOLUCAO = 'Endereço desatualizado'
                      AND nf.DT_DEVOLUCAO > v_dt_atualizacao) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN13: mercadoria devolvida por endereço desatualizado. Revalide o cadastro antes do pedido.';
        END IF;

        IF DATEDIFF(NEW.DT_DATA_DO_PEDIDO, v_dt_atualizacao) > 90 THEN    -- RN09 / RF09
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN09: cadastro sem confirmação há mais de 90 dias. Atualize o cliente antes do pedido.';
        END IF;

        IF v_situacao = 'Bloqueado Serasa' AND v_forma = 'Boleto' THEN    -- RN03
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN03: cliente com restrição no Serasa só compra no PIX ou no cartão.';
        END IF;

        IF v_forma = 'Boleto' AND NEW.VL_VALOR_VENDA > v_limite THEN      -- RN02 / RF02
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN02: valor do pedido acima do limite de crédito do cliente.';
        END IF;
    END IF;
END$$

-- RN07 / RF05: o preço praticado fica gravado para sempre.
CREATE TRIGGER TRG_ITEM_PEDIDO_PRECO_FIXO
BEFORE UPDATE ON ITEM_PEDIDO
FOR EACH ROW
BEGIN
    IF NEW.VL_UNITARIO_VENDIDO <> OLD.VL_UNITARIO_VENDIDO THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN07: o preço praticado na venda não pode ser alterado.';
    END IF;
END$$

DELIMITER ;


-- ============================================================
-- 4. INSERT (massa de dados fictícia)
-- Inserida na mesma ordem em que as tabelas foram criadas.
-- ============================================================

-- Por que este volume (seção 4 do esqueleto)
-- A Rafimex tem cerca de 10.000 clientes ativos, 1.550 produtos, 22 pessoas
-- na equipe comercial e 5 a 10 pedidos por dia útil (140 a 200 por mês).
-- A massa cobre um trimestre completo de operação (ago a out/2026):
--
--   Tabela              Registros  Origem do número
--   COLABORADOR                22  igual ao real: 20 representantes externos + 2 vendedores internos
--   CLIENTE                    50  amostra dos clientes mais ativos da carteira de ~10.000
--   PRODUTO                    60  as linhas mais vendidas do catálogo de 1.550 itens
--   FORNECEDOR                 10  fornecedores homologados que atendem esses produtos
--   PEDIDO                    460  ~153 por mês = 5 a 10 por dia útil, como na operação real
--   ITEM_PEDIDO              1309  média de 2.8 itens por pedido
--   NOTA_FISCAL               387  uma por pedido faturado
--   TITULO_RECEBER            542  um título por parcela (107 boletos parcelados em 2x ou 3x)
--     (das notas, 8 tiveram devolução: endereço desatualizado, avaria ou recusa)
--   COMPRA_IMPORTACAO          18  reposições nacionais e importações de jun a out/2026, com a conta a pagar de cada uma
--
-- Situações incluídas de propósito, para as consultas terem o que mostrar:
--   cadastrados sem nenhuma compra .... 16, 38, 42, 47 (os inativos são 16);
--                                       outros clientes só não compraram neste trimestre
--   restrição no Serasa (RN03) ........ 13, 29
--   inadimplentes (RN04) .............. 33, 48
--   cadastro vencido > 90 dias (RN09) . 1, 5, 26, 32  (além deles, outros clientes da massa nova também têm data antiga)
--   devolução por endereço (RN13) ..... revalidaram: 20, 27; ainda bloqueados: 10, 15
--   pedidos cancelados, produtos abaixo do ponto de pedido, entregas programadas,
--   importação atrasada, boletos vencidos e conta a pagar vencida.

