-- ============================================================
-- 5. SELECT COM JOIN
-- ============================================================

-- 5.1 Quais produtos foram vendidos nos pedidos de outubro, para quem, por qual representante e com que entrega?
SELECT
    p.ID_PEDIDO,
    p.DT_DATA_DO_PEDIDO,
    c.NM_RAZAO_SOCIAL                        AS CLIENTE,
    col.NM_COLABORADOR                       AS REPRESENTANTE,
    pr.DS_DESCRICAO                          AS PRODUTO,
    ip.QT_VENDIDA,
    ip.VL_UNITARIO_VENDIDO,
    ip.QT_VENDIDA * ip.VL_UNITARIO_VENDIDO   AS SUBTOTAL,
    IF(ip.DT_PREVISAO_CHEGADA IS NOT NULL, CONCAT('Programada p/ ', DATE_FORMAT(ip.DT_PREVISAO_CHEGADA, '%d/%m/%Y')), 'Estoque') AS ENTREGA
FROM PEDIDO p
JOIN CLIENTE c       ON c.ID_CLIENTE       = p.ID_CLIENTE
JOIN COLABORADOR col ON col.ID_COLABORADOR = p.ID_COLABORADOR
JOIN ITEM_PEDIDO ip  ON ip.ID_PEDIDO       = p.ID_PEDIDO
JOIN PRODUTO pr      ON pr.ID_PRODUTO      = ip.ID_PRODUTO
WHERE p.DT_DATA_DO_PEDIDO >= '2026-10-01'
ORDER BY p.ID_PEDIDO, pr.DS_DESCRICAO;

-- 5.2 Quais notas fiscais foram emitidas, para qual cliente, com qual frete e forma de pagamento, em quantas parcelas e quantas já foram pagas?
SELECT
    nf.NR_NF,
    nf.DT_DATA_EMISSAO,
    c.NM_RAZAO_SOCIAL                       AS CLIENTE,
    tf.DS_TIPO_FRETE                        AS FRETE,
    fp.DS_FORMA_PAGAMENTO                   AS PAGAMENTO,
    nf.VL_TOTAL_NF,
    nf.DS_STATUS_NF,
    COUNT(cr.ID_TITULO)                     AS PARCELAS,
    SUM(cr.ST_STATUS_TITULO = 'Pago')       AS PARCELAS_PAGAS,
    MAX(cr.DT_VENCIMENTO)                   AS ULTIMO_VENCIMENTO
FROM NOTA_FISCAL nf
JOIN PEDIDO p           ON p.ID_PEDIDO           = nf.ID_PEDIDO
JOIN CLIENTE c          ON c.ID_CLIENTE          = p.ID_CLIENTE
JOIN TIPO_FRETE tf      ON tf.ID_TIPO_FRETE      = p.ID_TIPO_FRETE
JOIN FORMA_PAGAMENTO fp ON fp.ID_FORMA_PAGAMENTO = p.ID_FORMA_PAGAMENTO
JOIN TITULO_RECEBER cr  ON cr.ID_NF              = nf.ID_NF
GROUP BY nf.ID_NF, nf.NR_NF, nf.DT_DATA_EMISSAO, c.NM_RAZAO_SOCIAL, tf.DS_TIPO_FRETE,
         fp.DS_FORMA_PAGAMENTO, nf.VL_TOTAL_NF, nf.DS_STATUS_NF
ORDER BY nf.NR_NF;

-- 5.3 Quais fornecedores atendem cada produto?
SELECT
    pr.CD_SKU,
    pr.DS_DESCRICAO,
    GROUP_CONCAT(f.NM_RAZAO_SOCIAL ORDER BY f.NM_RAZAO_SOCIAL SEPARATOR ' / ') AS FORNECEDORES
FROM PRODUTO pr
JOIN FORNECEDOR_PRODUTO fp ON fp.ID_PRODUTO   = pr.ID_PRODUTO
JOIN FORNECEDOR f          ON f.ID_FORNECEDOR = fp.ID_FORNECEDOR
GROUP BY pr.ID_PRODUTO, pr.CD_SKU, pr.DS_DESCRICAO
ORDER BY pr.CD_SKU;

-- 5.4 Qual é a carteira de cada colaborador (quantos clientes e quantos pedidos)?
SELECT
    col.NM_COLABORADOR,
    tc.DS_TIPO_COLABORADOR,
    COUNT(DISTINCT c.ID_CLIENTE) AS QTD_CLIENTES,
    COUNT(DISTINCT p.ID_PEDIDO)  AS QTD_PEDIDOS_DA_CARTEIRA
FROM COLABORADOR col
JOIN TIPO_COLABORADOR tc ON tc.ID_TIPO_COLABORADOR = col.ID_TIPO_COLABORADOR
LEFT JOIN CLIENTE c      ON c.ID_COLABORADOR = col.ID_COLABORADOR
LEFT JOIN PEDIDO p       ON p.ID_CLIENTE     = c.ID_CLIENTE
GROUP BY col.ID_COLABORADOR, col.NM_COLABORADOR, tc.DS_TIPO_COLABORADOR
ORDER BY QTD_PEDIDOS_DA_CARTEIRA DESC;

-- 5.5 Quais compras e importações estão em aberto, de qual fornecedor e com que conta a pagar?
SELECT
    pc.NR_NUMERO_COMPRA,
    pc.TP_TIPO_OPERACAO,
    f.NM_RAZAO_SOCIAL AS FORNECEDOR,
    pc.DS_INCOTERM,
    pc.CD_MOEDA,
    pc.DT_DATA_COMPRA,
    pc.DT_PREVISAO_CHEGADA,
    pc.VL_VALOR_TOTAL,
    pc.DT_VENCIMENTO_PAGAMENTO,
    pc.ST_STATUS_PAGAMENTO
FROM COMPRA_IMPORTACAO pc
JOIN FORNECEDOR f ON f.ID_FORNECEDOR = pc.ID_FORNECEDOR
WHERE pc.ST_STATUS_COMPRA = 'Pendente'
ORDER BY pc.DT_PREVISAO_CHEGADA;


-- ============================================================
-- 6. UPDATE
-- ============================================================
SET SQL_SAFE_UPDATES = 0;   -- o Workbench bloqueia UPDATE/DELETE sem chave no WHERE

-- 6.1 Cliente com cadastro vencido confirmou os dados pelo Portal de Confirmação Ativa: reinicia a trava de 90 dias (RN09)
UPDATE CLIENTE
SET DT_DATA_DE_ATUALIZACAO = CURDATE()
WHERE ID_CLIENTE = 1;

-- 6.2 Cliente bloqueado por devolução informou o endereço novo: corrige o cadastro e libera novos pedidos (RN13)
UPDATE CLIENTE
SET DS_RUA = 'Rua Nova Esperança',
    NR_NUMERO = '120',
    DS_COMPLEMENTO = 'Galpão 2',
    DT_DATA_DE_ATUALIZACAO = CURDATE()
WHERE ID_CLIENTE = 15;

-- 6.3 Cliente pagou uma parcela de boleto que estava vencida: baixa no título, o que libera a comissão dessa parcela (RN12)
UPDATE TITULO_RECEBER
SET DT_PAGAMENTO = CURDATE(),
    ST_STATUS_TITULO = 'Pago'
WHERE ID_TITULO = 168 AND ST_STATUS_TITULO = 'Aberto';

-- 6.4 Financeiro pagou o fornecedor da compra que estava com o pagamento vencido (RN11)
UPDATE COMPRA_IMPORTACAO
SET DT_PAGAMENTO = CURDATE(),
    ST_STATUS_PAGAMENTO = 'Pago'
WHERE ID_COMPRA = 14 AND ST_STATUS_PAGAMENTO = 'Pendente';

-- 6.5 Reajuste de 5% na tabela de preços dos produtos da Nova Era Soluções Empresariais (fornecedor 2).
-- Os itens já vendidos continuam com o preço antigo (RN07): confira na consulta A09.
UPDATE PRODUTO
SET VL_PRECO_UNITARIO = ROUND(VL_PRECO_UNITARIO * 1.05, 2)
WHERE ID_PRODUTO IN (SELECT ID_PRODUTO FROM FORNECEDOR_PRODUTO WHERE ID_FORNECEDOR = 2);

-- 6.6 Chegou a importação 18: soma as quantidades no estoque e registra o recebimento
UPDATE PRODUTO pr
JOIN ITEM_COMPRA ipc ON ipc.ID_PRODUTO = pr.ID_PRODUTO
JOIN COMPRA_IMPORTACAO pc       ON pc.ID_COMPRA = ipc.ID_COMPRA
SET pr.QT_ESTOQUE = pr.QT_ESTOQUE + ipc.QT_COMPRADA
WHERE pc.ID_COMPRA = 18 AND pc.ST_STATUS_COMPRA = 'Pendente';

UPDATE COMPRA_IMPORTACAO
SET ST_STATUS_COMPRA = 'Recebido',
    DT_DATA_RECEBIMENTO = CURDATE()
WHERE ID_COMPRA = 18;

-- 6.7 Pedido pendente liberado pelo financeiro: vai para a separação
UPDATE PEDIDO
SET ID_STATUS_PEDIDO = (SELECT ID_STATUS_PEDIDO FROM STATUS_PEDIDO WHERE DS_STATUS_PEDIDO = 'Em Separação')
WHERE ID_PEDIDO = 399;


-- ============================================================
-- 7. DELETE
-- Pedido com nota fiscal, cliente com pedido e produto já vendido
-- não podem ser apagados: as FKs bloqueiam (RNF02).
-- ============================================================

-- 7.1 Pedido cancelado lançado em duplicidade (não tem NF). Os itens saem juntos (ON DELETE CASCADE).
DELETE FROM PEDIDO
WHERE ID_PEDIDO = 177
  AND ID_STATUS_PEDIDO = (SELECT ID_STATUS_PEDIDO FROM STATUS_PEDIDO WHERE DS_STATUS_PEDIDO = 'Cancelado');

-- 7.2 Compra cancelada, sem conta a pagar. Os itens saem juntos (ON DELETE CASCADE).
DELETE FROM COMPRA_IMPORTACAO
WHERE ID_COMPRA = 13
  AND ST_STATUS_COMPRA = 'Cancelado';

-- 7.3 A Oliveira Materiais Industriais deixou de fornecer a 9018 TOALHA DE MESA 1,80M X 3,55M BRANCO
DELETE FROM FORNECEDOR_PRODUTO
WHERE ID_FORNECEDOR = 5 AND ID_PRODUTO = 22;

-- 7.4 Clientes inativos que nunca compraram (cadastros de prospecção antigos)
DELETE FROM CLIENTE
WHERE IN_ATIVO = FALSE
  AND NOT EXISTS (SELECT 1 FROM PEDIDO p WHERE p.ID_CLIENTE = CLIENTE.ID_CLIENTE);

SET SQL_SAFE_UPDATES = 1;


-- ============================================================
-- 8. CONSULTAS GERENCIAIS
-- ============================================================

-- G01 — Quanto a Rafimex faturou por mês e qual foi o ticket médio?
-- Atende: K1 (faturamento mensal e ticket médio)
SELECT
    DATE_FORMAT(nf.DT_DATA_EMISSAO, '%Y-%m') AS MES,
    COUNT(*)                                 AS QTD_NOTAS,
    SUM(nf.VL_TOTAL_NF)                      AS FATURAMENTO,
    ROUND(AVG(nf.VL_TOTAL_NF), 2)            AS TICKET_MEDIO
FROM NOTA_FISCAL nf
WHERE nf.DS_STATUS_NF = 'Emitida'
GROUP BY MES
ORDER BY MES;

-- G02 — Quais cadastros vão vencer nos próximos 15 dias e quem deve pedir a confirmação?
-- Atende: P1 (aviso ANTES de o cadastro vencer), RF09
SELECT
    col.NM_COLABORADOR                                     AS REPRESENTANTE,
    c.ID_CLIENTE,
    c.NM_RAZAO_SOCIAL,
    c.DS_EMAIL,
    CONCAT('(', c.CD_DDD, ') ', c.NR_NUMERO_TEL)           AS TELEFONE,
    DATE_ADD(c.DT_DATA_DE_ATUALIZACAO, INTERVAL 90 DAY)    AS VENCE_EM,
    DATEDIFF(DATE_ADD(c.DT_DATA_DE_ATUALIZACAO, INTERVAL 90 DAY), CURDATE()) AS DIAS_RESTANTES
FROM CLIENTE c
JOIN COLABORADOR col ON col.ID_COLABORADOR = c.ID_COLABORADOR
WHERE c.IN_ATIVO = TRUE
  AND DATE_ADD(c.DT_DATA_DE_ATUALIZACAO, INTERVAL 90 DAY) BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 15 DAY)
ORDER BY VENCE_EM, REPRESENTANTE;

-- G03 — Que percentual da carteira de cada representante está com o cadastro vencido?
-- Atende: P1, K2 (% da carteira com cadastro vencido)
SELECT
    col.NM_COLABORADOR,
    COUNT(*)                                                               AS CLIENTES_ATIVOS,
    SUM(DATEDIFF(CURDATE(), c.DT_DATA_DE_ATUALIZACAO) > 90)                AS CADASTROS_VENCIDOS,
    ROUND(100 * SUM(DATEDIFF(CURDATE(), c.DT_DATA_DE_ATUALIZACAO) > 90) / COUNT(*), 1) AS PCT_VENCIDOS
FROM COLABORADOR col
JOIN CLIENTE c ON c.ID_COLABORADOR = col.ID_COLABORADOR
WHERE c.IN_ATIVO = TRUE
GROUP BY col.ID_COLABORADOR, col.NM_COLABORADOR
ORDER BY PCT_VENCIDOS DESC, col.NM_COLABORADOR;

-- G04 — Qual é a taxa de inadimplência das parcelas de boleto, por mês de vencimento?
-- Atende: P2, K3 (taxa de inadimplência)
SELECT
    DATE_FORMAT(cr.DT_VENCIMENTO, '%Y-%m')                                  AS MES_VENCIMENTO,
    COUNT(*)                                                                AS PARCELAS_VENCIDAS_ATE_HOJE,
    SUM(cr.VL_PARCELA)                                                        AS VALOR_TOTAL,
    SUM(CASE WHEN cr.ST_STATUS_TITULO = 'Aberto' THEN cr.VL_PARCELA ELSE 0 END) AS VALOR_NAO_PAGO,
    ROUND(100 * SUM(CASE WHEN cr.ST_STATUS_TITULO = 'Aberto' THEN cr.VL_PARCELA ELSE 0 END) / SUM(cr.VL_PARCELA), 1) AS TAXA_INADIMPLENCIA_PCT
FROM TITULO_RECEBER cr
JOIN NOTA_FISCAL nf     ON nf.ID_NF              = cr.ID_NF
JOIN PEDIDO p           ON p.ID_PEDIDO           = nf.ID_PEDIDO
JOIN FORMA_PAGAMENTO fp ON fp.ID_FORMA_PAGAMENTO = p.ID_FORMA_PAGAMENTO
WHERE fp.DS_FORMA_PAGAMENTO = 'Boleto'
  AND cr.ST_STATUS_TITULO <> 'Cancelado'
  AND cr.DT_VENCIMENTO < CURDATE()
GROUP BY MES_VENCIMENTO
ORDER BY MES_VENCIMENTO;

-- G05 — Quantas entregas voltaram por mês, por qual motivo, e quanto custaram de reentrega?
-- Atende: P3, K4 (taxa de devolução e custo de reentrega)
SELECT
    DATE_FORMAT(nf.DT_DATA_EMISSAO, '%Y-%m')                     AS MES,
    COUNT(*)                                                     AS NOTAS_EMITIDAS,
    COUNT(nf.DT_DEVOLUCAO)                                       AS DEVOLUCOES,
    COALESCE(SUM(nf.DS_MOTIVO_DEVOLUCAO = 'Endereço desatualizado'), 0) AS POR_ENDERECO_DESATUALIZADO,
    ROUND(100 * COUNT(nf.DT_DEVOLUCAO) / COUNT(*), 2)            AS TAXA_DEVOLUCAO_PCT,
    COALESCE(SUM(nf.VL_TAXA_REENTREGA), 0)                       AS CUSTO_REENTREGA
FROM NOTA_FISCAL nf
WHERE nf.DS_STATUS_NF = 'Emitida'
GROUP BY MES
ORDER BY MES;

-- G06 — Quanto de comissão cada colaborador recebe em outubro/2026 e quanto ainda está retido?
-- Atende: K5, RN12 (8% externo / 3% interno, liberada só depois do pagamento do título)
SELECT
    col.NM_COLABORADOR,
    tc.DS_TIPO_COLABORADOR,
    tc.VL_PERC_COMISSAO,
    ROUND(SUM(CASE WHEN cr.ST_STATUS_TITULO = 'Pago' AND cr.DT_PAGAMENTO BETWEEN '2026-10-01' AND '2026-10-31'
                   THEN cr.VL_PARCELA ELSE 0 END) * tc.VL_PERC_COMISSAO / 100, 2) AS COMISSAO_LIBERADA_OUT,
    ROUND(SUM(CASE WHEN cr.ST_STATUS_TITULO = 'Aberto'
                   THEN cr.VL_PARCELA ELSE 0 END) * tc.VL_PERC_COMISSAO / 100, 2) AS COMISSAO_RETIDA
FROM COLABORADOR col
JOIN TIPO_COLABORADOR tc ON tc.ID_TIPO_COLABORADOR = col.ID_TIPO_COLABORADOR
JOIN PEDIDO p            ON p.ID_COLABORADOR       = col.ID_COLABORADOR
JOIN NOTA_FISCAL nf      ON nf.ID_PEDIDO           = p.ID_PEDIDO
JOIN TITULO_RECEBER cr ON cr.ID_NF               = nf.ID_NF
GROUP BY col.ID_COLABORADOR, col.NM_COLABORADOR, tc.DS_TIPO_COLABORADOR, tc.VL_PERC_COMISSAO
ORDER BY COMISSAO_LIBERADA_OUT DESC;

-- G07 — Quais são os 10 clientes que mais compraram no trimestre?
-- Atende: decisão comercial (foco da carteira dos representantes)
SELECT
    c.NM_RAZAO_SOCIAL,
    c.DS_CIDADE,
    COUNT(nf.ID_NF)      AS QTD_NOTAS,
    SUM(nf.VL_TOTAL_NF)  AS FATURAMENTO_TOTAL
FROM CLIENTE c
JOIN PEDIDO p       ON p.ID_CLIENTE = c.ID_CLIENTE
JOIN NOTA_FISCAL nf ON nf.ID_PEDIDO = p.ID_PEDIDO AND nf.DS_STATUS_NF = 'Emitida'
GROUP BY c.ID_CLIENTE, c.NM_RAZAO_SOCIAL, c.DS_CIDADE
ORDER BY FATURAMENTO_TOTAL DESC
LIMIT 10;

-- G08 — Quais são os 10 produtos mais vendidos e quanto deram de margem bruta?
-- Atende: decisão de compras e importação (o que repor primeiro)
SELECT
    pr.CD_SKU,
    pr.DS_DESCRICAO,
    SUM(ip.QT_VENDIDA)                                                AS UNIDADES,
    SUM(ip.QT_VENDIDA * ip.VL_UNITARIO_VENDIDO)                       AS RECEITA,
    SUM(ip.QT_VENDIDA * (ip.VL_UNITARIO_VENDIDO - pr.VL_PRECO_CUSTO)) AS MARGEM_BRUTA
FROM ITEM_PEDIDO ip
JOIN PRODUTO pr      ON pr.ID_PRODUTO      = ip.ID_PRODUTO
JOIN PEDIDO p        ON p.ID_PEDIDO        = ip.ID_PEDIDO
JOIN STATUS_PEDIDO s ON s.ID_STATUS_PEDIDO = p.ID_STATUS_PEDIDO
WHERE s.DS_STATUS_PEDIDO <> 'Cancelado'
GROUP BY pr.ID_PRODUTO, pr.CD_SKU, pr.DS_DESCRICAO
ORDER BY UNIDADES DESC
LIMIT 10;

-- G09 — Qual é a taxa de cancelamento de pedidos por mês?
-- Atende: K6 (taxa de cancelamento)
SELECT
    DATE_FORMAT(p.DT_DATA_DO_PEDIDO, '%Y-%m')                        AS MES,
    COUNT(*)                                                         AS TOTAL_PEDIDOS,
    SUM(s.DS_STATUS_PEDIDO = 'Cancelado')                            AS CANCELADOS,
    ROUND(100 * SUM(s.DS_STATUS_PEDIDO = 'Cancelado') / COUNT(*), 1) AS TAXA_CANCELAMENTO_PCT
FROM PEDIDO p
JOIN STATUS_PEDIDO s ON s.ID_STATUS_PEDIDO = p.ID_STATUS_PEDIDO
GROUP BY MES
ORDER BY MES;

-- G10 — Quais produtos estão abaixo do ponto de pedido e quanto já está a caminho?
-- Atende: RF08 (alerta preventivo de reposição)
SELECT
    pr.CD_SKU,
    pr.DS_DESCRICAO,
    pr.QT_ESTOQUE,
    pr.QT_PONTO_PEDIDO,
    COALESCE(cam.QT_A_CAMINHO, 0) AS QT_A_CAMINHO,
    cam.PROXIMA_CHEGADA
FROM PRODUTO pr
LEFT JOIN (
    SELECT ipc.ID_PRODUTO,
           SUM(ipc.QT_COMPRADA)      AS QT_A_CAMINHO,
           MIN(pc.DT_PREVISAO_CHEGADA) AS PROXIMA_CHEGADA
    FROM ITEM_COMPRA ipc
    JOIN COMPRA_IMPORTACAO pc ON pc.ID_COMPRA = ipc.ID_COMPRA
    WHERE pc.ST_STATUS_COMPRA = 'Pendente'
    GROUP BY ipc.ID_PRODUTO
) cam ON cam.ID_PRODUTO = pr.ID_PRODUTO
WHERE pr.QT_ESTOQUE <= pr.QT_PONTO_PEDIDO
ORDER BY pr.QT_ESTOQUE;

-- G11 — Como as vendas se dividem por forma de pagamento?
-- Atende: análise de crédito (quanto da venda depende de boleto - RN02)
SELECT
    fp.DS_FORMA_PAGAMENTO,
    COUNT(*)                                                 AS QTD_PEDIDOS,
    SUM(p.VL_VALOR_VENDA)                                    AS VALOR_TOTAL,
    ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM PEDIDO), 1) AS PCT_PEDIDOS
FROM PEDIDO p
JOIN FORMA_PAGAMENTO fp ON fp.ID_FORMA_PAGAMENTO = p.ID_FORMA_PAGAMENTO
GROUP BY fp.ID_FORMA_PAGAMENTO, fp.DS_FORMA_PAGAMENTO
ORDER BY QTD_PEDIDOS DESC;

-- G12 — Os fornecedores cumprem a data de chegada prometida? (atraso médio das compras recebidas)
-- Atende: RN08 (a data prometida ao cliente na entrega programada depende dessa previsão)
SELECT
    f.NM_RAZAO_SOCIAL                                                   AS FORNECEDOR,
    pc.TP_TIPO_OPERACAO,
    COUNT(*)                                                            AS COMPRAS_RECEBIDAS,
    ROUND(AVG(DATEDIFF(pc.DT_DATA_RECEBIMENTO, pc.DT_PREVISAO_CHEGADA)), 1) AS ATRASO_MEDIO_DIAS,
    SUM(pc.DT_DATA_RECEBIMENTO > pc.DT_PREVISAO_CHEGADA)                AS CHEGADAS_ATRASADAS
FROM COMPRA_IMPORTACAO pc
JOIN FORNECEDOR f ON f.ID_FORNECEDOR = pc.ID_FORNECEDOR
WHERE pc.ST_STATUS_COMPRA = 'Recebido'
GROUP BY f.ID_FORNECEDOR, f.NM_RAZAO_SOCIAL, pc.TP_TIPO_OPERACAO
ORDER BY ATRASO_MEDIO_DIAS DESC;


-- ============================================================
-- 9. CONSULTAS DE AUDITORIA
-- ============================================================

-- A01 — Quais clientes estão com o cadastro sem confirmação há mais de 90 dias?
-- Verifica: RN09 / RF09
SELECT
    c.ID_CLIENTE,
    c.NM_RAZAO_SOCIAL,
    col.NM_COLABORADOR AS REPRESENTANTE,
    c.DT_DATA_DE_ATUALIZACAO,
    DATEDIFF(CURDATE(), c.DT_DATA_DE_ATUALIZACAO) AS DIAS_SEM_ATUALIZAR
FROM CLIENTE c
JOIN COLABORADOR col ON col.ID_COLABORADOR = c.ID_COLABORADOR
WHERE DATEDIFF(CURDATE(), c.DT_DATA_DE_ATUALIZACAO) > 90
ORDER BY DIAS_SEM_ATUALIZAR DESC;

-- A02 — Quais clientes tiveram mercadoria devolvida por endereço errado e ainda não revalidaram o cadastro?
-- Verifica: RN13
SELECT
    c.ID_CLIENTE,
    c.NM_RAZAO_SOCIAL,
    nf.NR_NF,
    nf.DT_DEVOLUCAO,
    nf.VL_TAXA_REENTREGA,
    c.DT_DATA_DE_ATUALIZACAO
FROM NOTA_FISCAL nf
JOIN PEDIDO p  ON p.ID_PEDIDO  = nf.ID_PEDIDO
JOIN CLIENTE c ON c.ID_CLIENTE = p.ID_CLIENTE
WHERE nf.DS_MOTIVO_DEVOLUCAO = 'Endereço desatualizado'
  AND nf.DT_DEVOLUCAO > c.DT_DATA_DE_ATUALIZACAO;

-- A03 — Há pedidos em aberto de clientes com restrição de crédito? (devem ser segurados)
-- Verifica: RN03, RN04, RF02
SELECT
    p.ID_PEDIDO,
    p.DT_DATA_DO_PEDIDO,
    c.NM_RAZAO_SOCIAL,
    c.ST_SITUACAO_CREDITO,
    fp.DS_FORMA_PAGAMENTO,
    s.DS_STATUS_PEDIDO,
    p.VL_VALOR_VENDA
FROM PEDIDO p
JOIN CLIENTE c          ON c.ID_CLIENTE          = p.ID_CLIENTE
JOIN STATUS_PEDIDO s    ON s.ID_STATUS_PEDIDO    = p.ID_STATUS_PEDIDO
JOIN FORMA_PAGAMENTO fp ON fp.ID_FORMA_PAGAMENTO = p.ID_FORMA_PAGAMENTO
WHERE s.DS_STATUS_PEDIDO IN ('Pendente', 'Em Separação')
  AND c.ST_SITUACAO_CREDITO <> 'Ativo';

-- A04 — Há clientes marcados como "Ativo" com boleto vencido e não pago? (deveriam ser revistos)
-- Verifica: RN04 (pendência com a Rafimex bloqueia vendas)
SELECT
    c.ID_CLIENTE,
    c.NM_RAZAO_SOCIAL,
    c.ST_SITUACAO_CREDITO,
    nf.NR_NF,
    cr.NR_PARCELA,
    cr.DT_VENCIMENTO,
    DATEDIFF(CURDATE(), cr.DT_VENCIMENTO) AS DIAS_DE_ATRASO,
    cr.VL_PARCELA
FROM TITULO_RECEBER cr
JOIN NOTA_FISCAL nf ON nf.ID_NF     = cr.ID_NF
JOIN PEDIDO p       ON p.ID_PEDIDO  = nf.ID_PEDIDO
JOIN CLIENTE c      ON c.ID_CLIENTE = p.ID_CLIENTE
WHERE cr.ST_STATUS_TITULO = 'Aberto'
  AND cr.DT_VENCIMENTO < CURDATE()
  AND c.ST_SITUACAO_CREDITO = 'Ativo'
ORDER BY DIAS_DE_ATRASO DESC;

-- A05 — Quais contas a pagar estão vencidas e ainda não foram pagas?
-- Verifica: RN11 (toda importação recebida alimenta o contas a pagar e precisa ser quitada)
SELECT
    pc.NR_NUMERO_COMPRA,
    f.NM_RAZAO_SOCIAL AS FORNECEDOR,
    pc.DT_VENCIMENTO_PAGAMENTO,
    DATEDIFF(CURDATE(), pc.DT_VENCIMENTO_PAGAMENTO) AS DIAS_DE_ATRASO,
    pc.VL_VALOR_TOTAL
FROM COMPRA_IMPORTACAO pc
JOIN FORNECEDOR f ON f.ID_FORNECEDOR = pc.ID_FORNECEDOR
WHERE pc.ST_STATUS_PAGAMENTO = 'Pendente'
  AND pc.DT_VENCIMENTO_PAGAMENTO < CURDATE();

-- A06 — Quais itens de entrega programada já passaram da data prometida ao cliente?
-- Verifica: RN08, RF07
SELECT
    ip.ID_PEDIDO,
    c.NM_RAZAO_SOCIAL AS CLIENTE,
    pr.DS_DESCRICAO,
    ip.QT_VENDIDA,
    ip.DT_PREVISAO_CHEGADA
FROM ITEM_PEDIDO ip
JOIN PEDIDO p   ON p.ID_PEDIDO   = ip.ID_PEDIDO
JOIN CLIENTE c  ON c.ID_CLIENTE  = p.ID_CLIENTE
JOIN PRODUTO pr ON pr.ID_PRODUTO = ip.ID_PRODUTO
WHERE ip.DT_PREVISAO_CHEGADA < CURDATE();

-- A07 — Há pedido faturado sem nota, nota com valor diferente do pedido, ou nota cujas parcelas não somam o total? (o esperado é vazio)
-- Verifica: RN14 (pedido faturado tem uma nota), RNF02 (integridade do faturamento)
SELECT
    p.ID_PEDIDO,
    s.DS_STATUS_PEDIDO,
    p.VL_VALOR_VENDA,
    nf.NR_NF,
    nf.VL_TOTAL_NF,
    tit.QTD_PARCELAS,
    tit.SOMA_PARCELAS
FROM PEDIDO p
JOIN STATUS_PEDIDO s     ON s.ID_STATUS_PEDIDO = p.ID_STATUS_PEDIDO
LEFT JOIN NOTA_FISCAL nf ON nf.ID_PEDIDO       = p.ID_PEDIDO
LEFT JOIN (
    SELECT ID_NF, COUNT(*) AS QTD_PARCELAS, SUM(VL_PARCELA) AS SOMA_PARCELAS
    FROM TITULO_RECEBER
    GROUP BY ID_NF
) tit ON tit.ID_NF = nf.ID_NF
WHERE (s.DS_STATUS_PEDIDO = 'Faturado' AND nf.ID_NF IS NULL)
   OR (nf.ID_NF IS NOT NULL AND nf.VL_TOTAL_NF <> p.VL_VALOR_VENDA)
   OR (nf.ID_NF IS NOT NULL AND tit.ID_NF IS NULL)
   OR (nf.ID_NF IS NOT NULL AND tit.SOMA_PARCELAS <> nf.VL_TOTAL_NF);

-- A08 — Há pedidos sem nenhum item? (o esperado é vazio)
-- Verifica: RNF02 (nenhum pedido sem item)
SELECT p.ID_PEDIDO, p.DT_DATA_DO_PEDIDO
FROM PEDIDO p
LEFT JOIN ITEM_PEDIDO ip ON ip.ID_PEDIDO = p.ID_PEDIDO
WHERE ip.ID_PEDIDO IS NULL;

-- A09 — Quais vendas usaram um preço diferente da tabela atual? (prova de que o preço praticado ficou gravado)
-- Verifica: RN07, RF05
SELECT
    ip.ID_PEDIDO,
    p.DT_DATA_DO_PEDIDO,
    pr.DS_DESCRICAO,
    ip.VL_UNITARIO_VENDIDO AS PRECO_NA_VENDA,
    pr.VL_PRECO_UNITARIO   AS PRECO_ATUAL
FROM ITEM_PEDIDO ip
JOIN PEDIDO p   ON p.ID_PEDIDO   = ip.ID_PEDIDO
JOIN PRODUTO pr ON pr.ID_PRODUTO = ip.ID_PRODUTO
WHERE ip.VL_UNITARIO_VENDIDO <> pr.VL_PRECO_UNITARIO
ORDER BY p.DT_DATA_DO_PEDIDO DESC;

-- A10 — Quais pedidos tiveram desconto acima de 4%? (conferência das aprovações da diretoria)
-- Verifica: RN06, RF04
SELECT
    p.ID_PEDIDO,
    p.DT_DATA_DO_PEDIDO,
    c.NM_RAZAO_SOCIAL,
    col.NM_COLABORADOR,
    p.VL_DESCONTO_APLICADO,
    p.IN_APROVACAO_DIRETORIA
FROM PEDIDO p
JOIN CLIENTE c       ON c.ID_CLIENTE       = p.ID_CLIENTE
JOIN COLABORADOR col ON col.ID_COLABORADOR = p.ID_COLABORADOR
WHERE p.VL_DESCONTO_APLICADO > 4
ORDER BY p.VL_DESCONTO_APLICADO DESC;

-- A11 — Há pedido em aberto no boleto para cliente com restrição no Serasa ou acima do limite de crédito? (o esperado é vazio)
-- Verifica: RN02, RN03
SELECT
    p.ID_PEDIDO,
    c.NM_RAZAO_SOCIAL,
    c.ST_SITUACAO_CREDITO,
    c.VL_LIMITE_CREDITO,
    p.VL_VALOR_VENDA
FROM PEDIDO p
JOIN CLIENTE c          ON c.ID_CLIENTE          = p.ID_CLIENTE
JOIN STATUS_PEDIDO s    ON s.ID_STATUS_PEDIDO    = p.ID_STATUS_PEDIDO
JOIN FORMA_PAGAMENTO fp ON fp.ID_FORMA_PAGAMENTO = p.ID_FORMA_PAGAMENTO
WHERE fp.DS_FORMA_PAGAMENTO = 'Boleto'
  AND s.DS_STATUS_PEDIDO IN ('Pendente', 'Em Separação')
  AND (c.ST_SITUACAO_CREDITO = 'Bloqueado Serasa' OR p.VL_VALOR_VENDA > c.VL_LIMITE_CREDITO);

-- A12 — Quais clientes ativos nunca compraram?
-- Verifica: RNF01 (cadastros parados que precisam de revalidação ou desativação)
SELECT c.ID_CLIENTE, c.NM_RAZAO_SOCIAL, c.DS_CIDADE, c.DT_DATA_DE_ATUALIZACAO
FROM CLIENTE c
WHERE c.IN_ATIVO = TRUE
  AND NOT EXISTS (SELECT 1 FROM PEDIDO p WHERE p.ID_CLIENTE = c.ID_CLIENTE);


-- A13 — Algum perfil acessou dados fora da sua permissão?
-- Verifica: RNF04 (acesso restrito) e a matriz de papéis do dicionário de dados
SELECT
    l.DT_ACESSO,
    l.NM_USUARIO,
    l.DS_PERFIL,
    l.DS_OPERACAO,
    l.DS_TABELA_AFETADA
FROM LOG_ACESSO l
WHERE (l.DS_TABELA_AFETADA = 'COLABORADOR'    AND l.DS_PERFIL NOT IN ('RH','Administrador'))
   OR (l.DS_TABELA_AFETADA = 'TITULO_RECEBER' AND l.DS_PERFIL NOT IN ('Financeiro','Faturamento','Administrador'))
   OR (l.DS_OPERACAO = 'Apagar'               AND l.DS_PERFIL NOT IN ('RH','Administrador'))
ORDER BY l.DT_ACESSO;

-- A14 — Quem acessou os dados de crédito dos clientes no último mês? (rastreabilidade LGPD)
-- Verifica: RNF04, LGPD art. 6º, X (responsabilização)
SELECT
    l.DS_PERFIL,
    l.NM_USUARIO,
    COUNT(*)           AS ACESSOS,
    MAX(l.DT_ACESSO)   AS ULTIMO_ACESSO
FROM LOG_ACESSO l
WHERE l.DS_TABELA_AFETADA = 'CLIENTE'
  AND l.DT_ACESSO >= '2026-10-01'
GROUP BY l.DS_PERFIL, l.NM_USUARIO
ORDER BY ACESSOS DESC;


